-- Disposable CI fixture derived from the supplied ERD and repository SQL.
-- This is an application contract, not a migration or export of the live database.
CREATE TABLE IF NOT EXISTS public."USERS" (
    "User_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 3000000000) PRIMARY KEY,
    "User_Name" VARCHAR(40) NOT NULL UNIQUE,
    "User_Email" VARCHAR(320) NOT NULL UNIQUE,
    "Password_Hash" VARCHAR(255) NOT NULL,
    "Role" VARCHAR(20) NOT NULL DEFAULT 'FARMER' CHECK ("Role" IN ('FARMER','ADMIN'))
);
CREATE TABLE IF NOT EXISTS public."ACCOUNT_STATUS" (
    "User_ID" BIGINT PRIMARY KEY REFERENCES public."USERS" ON DELETE CASCADE,
    "Email_Verified" BOOLEAN NOT NULL DEFAULT FALSE,
    "Two_Factor_Enabled" BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE IF NOT EXISTS public."ACCOUNT_TOKENS" (
    "Token_ID" UUID PRIMARY KEY,
    "User_ID" BIGINT NOT NULL REFERENCES public."USERS" ON DELETE CASCADE,
    "Purpose" VARCHAR(30) NOT NULL CHECK ("Purpose" IN ('EMAIL_VERIFY','PASSWORD_RESET','LOGIN_2FA')),
    "Token_Hash" VARCHAR(128) NOT NULL UNIQUE,
    "Expires_At" TIMESTAMPTZ NOT NULL,
    "Used_At" TIMESTAMPTZ,
    "Created_At" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS public."FARMS" (
    "Farm_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "User_ID" BIGINT NOT NULL REFERENCES public."USERS" ON DELETE CASCADE,
    "Farm_Name" VARCHAR(100) NOT NULL,
    "Latitude" NUMERIC(9,6) NOT NULL CHECK ("Latitude" BETWEEN -90 AND 90),
    "Longitude" NUMERIC(9,6) NOT NULL CHECK ("Longitude" BETWEEN -180 AND 180),
    UNIQUE ("User_ID","Farm_Name")
);
CREATE TABLE IF NOT EXISTS public."CROP_TYPES" (
    "Crop_Type_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Crop_Name" VARCHAR(100) NOT NULL,
    "Variety" VARCHAR(100),
    "Optimal_Temp_Min" DOUBLE PRECISION,
    "Optimal_Temp_Max" DOUBLE PRECISION,
    "Optimal_Soil_Moisture_Min" DOUBLE PRECISION,
    "Optimal_Soil_Moisture_Max" DOUBLE PRECISION,
    "Optimal_pH_Min" DOUBLE PRECISION,
    "Optimal_pH_Max" DOUBLE PRECISION,
    "Optimal_Light_Min" DOUBLE PRECISION,
    "Optimal_Light_Max" DOUBLE PRECISION
);
CREATE TABLE IF NOT EXISTS public."CROP_CYCLES" (
    "Crop_Cycle_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Farm_ID" BIGINT NOT NULL REFERENCES public."FARMS" ON DELETE CASCADE,
    "Crop_Type_ID" BIGINT NOT NULL REFERENCES public."CROP_TYPES",
    "Date_Planted" TIMESTAMPTZ(0) NOT NULL,
    "Expected_Harvest_Date" DATE,
    "Actual_Harvest_Date" DATE,
    UNIQUE ("Farm_ID","Crop_Type_ID","Date_Planted")
);
-- Daily snapshots, matching CropWeatherRepository's ON CONFLICT key.
-- Weather_Date is the snapshot's reference day; this table does not compute averages.
CREATE TABLE IF NOT EXISTS public."CROP_WEATHER_READINGS" (
    "Crop_Cycle_ID" BIGINT PRIMARY KEY REFERENCES public."CROP_CYCLES" ON DELETE CASCADE,
    "Weather_Date" DATE NOT NULL,
    "Weather_Timezone" VARCHAR(100) NOT NULL,
    "Temperature_Mean_C" DOUBLE PRECISION CHECK ("Temperature_Mean_C" BETWEEN -100 AND 100),
    "Sunshine_Duration_Seconds" DOUBLE PRECISION CHECK ("Sunshine_Duration_Seconds" BETWEEN 0 AND 86400),
    "Humidity_Mean_Percent" DOUBLE PRECISION CHECK ("Humidity_Mean_Percent" BETWEEN 0 AND 100),
    "Soil_Moisture_Mean_M3M3" DOUBLE PRECISION CHECK ("Soil_Moisture_Mean_M3M3" BETWEEN 0 AND 1),
    "Weather_Source" VARCHAR(20) NOT NULL CHECK ("Weather_Source" IN ('MANUAL','OPEN_METEO'))
);
-- Historical averages use the separate table written by PR #27's CropRepository.
CREATE TABLE IF NOT EXISTS public."CROP_WEATHER_HISTORICAL_AVERAGE" (
    "Crop_Cycle_ID" BIGINT PRIMARY KEY REFERENCES public."CROP_CYCLES" ON DELETE CASCADE,
    "Start_Date" DATE NOT NULL,
    "End_Date" DATE NOT NULL,
    "Temperature_Mean" DOUBLE PRECISION CHECK ("Temperature_Mean" BETWEEN -100 AND 100),
    "Soil_Moisture_Mean" DOUBLE PRECISION CHECK ("Soil_Moisture_Mean" BETWEEN 0 AND 1),
    "Vapour_Pressure_Deficit_Mean" DOUBLE PRECISION CHECK ("Vapour_Pressure_Deficit_Mean" BETWEEN 0 AND 100),
    "Sunshine_Duration_Mean_Seconds" DOUBLE PRECISION CHECK ("Sunshine_Duration_Mean_Seconds" BETWEEN 0 AND 86400)
);
CREATE TABLE IF NOT EXISTS public."SENSORS" (
    "Sensor_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Farm_ID" BIGINT NOT NULL REFERENCES public."FARMS" ON DELETE CASCADE,
    "Sensor_Type" VARCHAR(100),
    "Reading" DOUBLE PRECISION,
    "Recorded_At" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS public."RISK_ASSESSMENTS" (
    "Assessment_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Crop_Cycle_ID" BIGINT NOT NULL REFERENCES public."CROP_CYCLES" ON DELETE CASCADE,
    "Risk_Level" VARCHAR(30),
    "Detected_Issue" TEXT,
    "Explanation" TEXT,
    "Predicted_Yield_Impact" DOUBLE PRECISION,
    "Assessed_At" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS public."RECOMMENDATIONS" (
    "Recommendation_ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Assessment_ID" BIGINT NOT NULL REFERENCES public."RISK_ASSESSMENTS" ON DELETE CASCADE,
    "Action" TEXT,
    "Confidence_Level" DOUBLE PRECISION,
    "Assumptions" TEXT,
    "Limitations" TEXT,
    "Review_Status" VARCHAR(30),
    "Created_At" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "Reviewed_At" TIMESTAMPTZ
);
